// ─── File: ProxyVsHiddenDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.pvh;

import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodHandles.Lookup.ClassOption;
import java.lang.reflect.Proxy;
import java.math.BigDecimal;
import java.util.logging.*;

public class ProxyVsHiddenDemo {
    private static final Logger log = Logger.getLogger(ProxyVsHiddenDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Throwable {
        // ---- Dynamic PROXY: named, registered, interface-based wrapper ----
        AccountService real = new RealAccountService();
        AccountService proxy = (AccountService) Proxy.newProxyInstance(
                AccountService.class.getClassLoader(),
                new Class<?>[]{ AccountService.class },        // interfaces only
                new LoggingHandler(real));
        log.info(() -> "Proxy class name = " + proxy.getClass().getName()); // e.g. jdk.proxyN/...$ProxyM
        log.info(() -> "Proxy balance SAV2001 = Rs." + proxy.getBalance("SAV2001"));

        // ---- HIDDEN class: nameless, unregistered, unloadable, NESTMATE access ----
        HiddenFactory factory = new HiddenFactory(new BigDecimal("0.001"));
        BigDecimal fee = factory.feeViaHidden(new BigDecimal("1000000"));
        log.info(() -> "Hidden class fee (NESTMATE read host private rate) = Rs." + fee);
    }
}

// ─── Would be in service/AccountService.java ───
interface AccountService {
    BigDecimal getBalance(String accountId);
}

// ─── Would be in service/RealAccountService.java ───
class RealAccountService implements AccountService {
    @Override public BigDecimal getBalance(String accountId) {
        // Rajesh SAV2001 1,000,000 ; Priya CUR3001 250,000
        return accountId.equals("SAV2001") ? new BigDecimal("1000000") : new BigDecimal("250000");
    }
}

// ─── Would be in proxy/LoggingHandler.java ───
class LoggingHandler implements java.lang.reflect.InvocationHandler {
    private static final Logger log = Logger.getLogger(LoggingHandler.class.getName());
    private final Object target;
    LoggingHandler(Object target) { this.target = target; }
    @Override public Object invoke(Object proxy, java.lang.reflect.Method method, Object[] args)
            throws Throwable {
        log.info(() -> "PROXY before " + method.getName() + " args=" + java.util.Arrays.toString(args));
        Object result = method.invoke(target, args);  // delegate to real object
        log.info(() -> "PROXY after  " + method.getName() + " result=" + result);
        return result;
    }
}

// ─── Host that defines a hidden class in ITS OWN module/package ───
class HiddenFactory {
    private final BigDecimal rate;                 // PRIVATE host state
    HiddenFactory(BigDecimal rate) { this.rate = rate; }
    BigDecimal rate() { return rate; }             // nestmate accessor

    BigDecimal feeViaHidden(BigDecimal amount) throws Throwable {
        byte[] bytes = readBytes("com/bank/pvh/HiddenCalc.class");
        MethodHandles.Lookup lookup = MethodHandles.lookup();
        // Hidden class defined in THIS lookup's module/package — no extra exports needed.
        Class<?> hidden = lookup.defineHiddenClass(bytes, true, ClassOption.NESTMATE).lookupClass();
        FeeRule rule = (FeeRule) hidden.getConstructor(HiddenFactory.class).newInstance(this);
        return rule.calculate(amount);
    }
    private static byte[] readBytes(String res) throws Exception {
        try (var in = HiddenFactory.class.getClassLoader().getResourceAsStream(res)) {
            if (in == null) throw new IllegalStateException("missing: " + res);
            return in.readAllBytes();
        }
    }
}

interface FeeRule { BigDecimal calculate(BigDecimal amount); }

// Payload for the hidden class — reads host private rate via NESTMATE accessor.
class HiddenCalc implements FeeRule {
    private final HiddenFactory host;
    HiddenCalc(HiddenFactory host) { this.host = host; }
    @Override public BigDecimal calculate(BigDecimal amount) {
        return amount.multiply(host.rate()).setScale(2, java.math.RoundingMode.HALF_UP);
    }
}

